tool_input.command:
node --test test/ 2>&1 | tail -12; echo '---'; node --input-type=module -e "
import { handle } from './src/api.js';
import { tick } from './src/scheduler.js';
for (const [tz, label] of [[330,'IST'],[-300,'UTC-5']]) {
  const { body } = handle({ method: 'POST', path: '/reminders', body: { userId: 'u'+tz, text: label, at: '2026-03-01T09:00', tzOffsetMin: tz } });
  console.log(label, 'due_ms stored =', new Date(body.due_ms).toISOString());
  // find first minute tick() delivers it
  for (let t = Date.parse('2026-02-28T12:00:00Z'); t < Date.parse('2026-03-02T00:00:00Z'); t += 60000) {
    const out = []; await tick(t, { formatter: 'legacy', out: (l) => out.push(l) });
    if (out.length) { console.log(label, 'delivered at', new Date(t).toISOString(), '->', out[0]); break; }
  }
}
const bad = handle({ method: 'POST', path: '/reminders', body: { userId: 'x', text: 't', at: '2026-03-01T09:00:00' } });
console.log('at with seconds -> status', bad.status, 'due_ms', bad.body.due_ms);
"
